const subscriptions = new Set();

export async function subscribeResource(uri) {
  if (typeof uri !== 'string' || uri.trim() === '') {
    const err = new Error('uri is required and must be a non-empty string');
    err.code = -32602;
    throw err;
  }
  if (subscriptions.has(uri)) {
    const err = new Error('already subscribed to ' + uri);
    err.code = -32602;
    throw err;
  }
  subscriptions.add(uri);
  return { subscribed: true, uri };
}

export async function unsubscribeResource(uri) {
  if (typeof uri !== 'string' || uri.trim() === '') {
    const err = new Error('uri is required and must be a non-empty string');
    err.code = -32602;
    throw err;
  }
  if (!subscriptions.has(uri)) {
    const err = new Error('not subscribed to ' + uri);
    err.code = -32602;
    throw err;
  }
  subscriptions.delete(uri);
  return { unsubscribed: true, uri };
}

const tools = [
  {
    name: 'subscribeResource',
    description: 'Subscribe to a resource identified by a non-empty URI.',
    inputSchema: {
      type: 'object',
      properties: {
        uri: { type: 'string', description: 'The non-empty resource URI to subscribe to.' }
      },
      required: ['uri'],
      additionalProperties: false
    }
  },
  {
    name: 'unsubscribeResource',
    description: 'Unsubscribe from a resource identified by its URI.',
    inputSchema: {
      type: 'object',
      properties: {
        uri: { type: 'string', description: 'The resource URI to unsubscribe from.' }
      },
      required: ['uri'],
      additionalProperties: false
    }
  }
];

export async function listTools() {
  return tools;
}

export async function callTool(name, args = {}) {
  if (name === 'subscribeResource') {
    return { content: [{ type: 'text', text: JSON.stringify(await subscribeResource(args.uri)) }] };
  }
  if (name === 'unsubscribeResource') {
    return { content: [{ type: 'text', text: JSON.stringify(await unsubscribeResource(args.uri)) }] };
  }
  const err = new Error('Method not found');
  err.code = -32601;
  throw err;
}
```

